/* ===================== BÀI 37 · Memory map, ROM và reset vector ===================== */
/* Bài 37 · Memory map, ROM và reset vector (AMTS-EMB-002-M10-L01, X86-037) — sinh bởi tools/author/mpu8086/l37.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P37=[{"label": "Ví dụ: địa chỉ của lệnh đầu tiên sau RESET", "code": "; Địa chỉ vật lý của lệnh đầu tiên sau RESET\n; CS = FFFFh, IP = 0000h → đoạn × 16 + độ lệch (20 bit)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ncsReset DW      0FFFFH                  ; CS sau RESET\nipReset DW      0000H                   ; IP sau RESET\nvlThap  DW      ?                       ; 16 bit thấp của địa chỉ vật lý\nvlCao   DB      ?                       ; 4 bit cao A19–A16\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, csReset             ; AX = FFFFh\n        MOV     DX, AX\n        MOV     CL, 4\n        SHL     AX, CL                  ; AX = FFF0h: 16 bit thấp của CS × 16\n        MOV     CL, 12\n        SHR     DX, CL                  ; DX = 000Fh: 4 bit cao của CS × 16\n        ADD     AX, ipReset             ; cộng độ lệch\n        ADC     DX, 0                   ; có nhớ thì cộng vào phần cao\n        MOV     vlThap, AX\n        MOV     vlCao, DL\n        MOV     AL, DL                  ; in A19–A16 (1 chữ số hex)\n        CALL    inNib\n        MOV     BX, vlThap              ; in A15–A0 (4 chữ số hex)\n        CALL    inHex4\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n\ninHex4  PROC                            ; in BX ra 4 chữ số hex\n        MOV     CH, 4\nlap4:\n        MOV     CL, 4\n        ROL     BX, CL                  ; 4 bit cao nhất xuống thấp nhất\n        MOV     AL, BL\n        CALL    inNib\n        DEC     CH\n        JNZ     lap4\n        RET\ninHex4  ENDP\n\ninNib   PROC                            ; in 4 bit thấp của AL (0–F)\n        AND     AL, 0FH\n        ADD     AL, '0'\n        CMP     AL, '9'\n        JBE     inNib1\n        ADD     AL, 7                   ; 3Ah → 41h ('A')\ninNib1:\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        RET\ninNib   ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước tới hết SHR DX, CL. SHL AX, 4 lấy 16 bit thấp của CS × 16 (FFF0h), SHR DX, 12 lấy 4 bit cao (Fh): địa chỉ 20 bit nằm trong cặp DX:AX. Chú ý chu kỳ SHL/SHR theo CL: 8 + 4 × số bit (24 và 56 chu kỳ). Màn hình in FFFF0. Đoán trước: sau SHL AX, CL, AX bằng bao nhiêu? Đáp án FFF0h."}, {"label": "Ví dụ: lệnh JMP xa đặt ở FFFF0h", "code": "; Lệnh JMP xa: dạng lệnh thường đặt ở FFFF0h\n; EA, độ lệch (2 byte), đoạn (2 byte), byte thấp trước\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        JMP     FAR PTR batDau          ; 5 byte: EA, IP mới, CS mới\nbatDau:\n        MOV     AH, 02H                 ; tới đây: CS:IP đã nạp lại\n        MOV     DL, 'J'\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Xem phần Mã máy và chu kỳ: JMP FAR PTR batDau dịch thành 5 byte EA 05 00 10 07: EAh, IP mới 0005h, CS mới 0710h (đoạn mã do trình mô phỏng nạp, giả định), byte thấp trước. Lệnh ở FFFF0h của bo thật có cùng dạng, chỉ khác giá trị CS:IP. JMP xa tốn 15 chu kỳ. Đoán trước: sau lệnh JMP, IP bằng bao nhiêu? Đáp án 0005h."}, {"label": "Ví dụ: chép dữ liệu khởi tạo ROM sang RAM", "code": "; Khởi động: chép dữ liệu khởi tạo từ ROM sang RAM\n; romDat giả lập bảng trong ROM, ramDat là biến trong RAM\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nromDat  DB      'AMTS 8086$'            ; 10 byte, có sẵn khi nạp\nramDat  DB      10 DUP(0)               ; RAM: lúc bật nguồn chưa có gì\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX                  ; MOVSB ghi vào ES:DI\n        MOV     SI, OFFSET romDat\n        MOV     DI, OFFSET ramDat\n        MOV     CX, 10\n        CLD                             ; SI, DI tăng dần\n        REP     MOVSB                   ; chép 10 byte\n        MOV     DX, OFFSET ramDat\n        MOV     AH, 09H                 ; in chuỗi đã chép (tới '$')\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bước 5 của chương trình khởi động: REP MOVSB chép 10 byte romDat (giả lập ROM) sang ramDat; xem phần Bộ nhớ, ramDat đổi từ 00 thành 41 4D 54 53… REP MOVSB tốn 9 + 17 × 10 = 179 chu kỳ. Phải đặt ES = DS vì MOVSB ghi vào ES:DI. Đoán trước: trước REP MOVSB, CX bằng bao nhiêu? Đáp án 000Ah."}, {"label": "Bẫy: FFFF:0010 chính là ô 00000h", "code": "; FFFF:0010 vượt 1 MB: trên 8086 địa chỉ quay về 00000h\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ncu      DB      ?                       ; byte cũ ở 0000:0000\ndoc     DB      ?                       ; byte đọc lại qua 0000:0000\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     AX, AX\n        MOV     ES, AX                  ; ES = 0000h\n        MOV     AL, ES:[0]              ; giữ byte cũ (vectơ ngắt 0)\n        MOV     cu, AL\n        MOV     AX, 0FFFFH\n        MOV     ES, AX                  ; ES = FFFFh\n        MOV     BYTE PTR ES:[10H], 5AH  ; FFFF0h + 10h = 100000h\n        XOR     AX, AX\n        MOV     ES, AX\n        MOV     AL, ES:[0]              ; đọc lại ở 00000h\n        MOV     doc, AL\n        MOV     AL, cu\n        MOV     ES:[0], AL              ; trả lại byte cũ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: ES = FFFFh và độ lệch 10h cho FFFF0h + 10h = 100000h, vượt 1 MB. 8086 bỏ bit thứ 21 nên ghi vào 00000h. Đọc lại qua 0000:0000 được 5Ah (biến doc), rồi chương trình trả lại byte cũ của vectơ ngắt 0. Đoán trước: biến doc bằng bao nhiêu? Đáp án 5Ah."}, {"label": "Lỗi: tính đầu ROM bằng 16 bit, mất A19–A16", "code": "; Tính địa chỉ đầu ROM 32 KB ở đỉnh bộ nhớ, nhưng\n; làm bằng thanh ghi 16 bit theo đơn vị byte\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndauRom  DW      ?                       ; mong đợi F8000h (20 bit)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     AX, AX                  ; \"100000h\" trong 16 bit là 0\n        SUB     AX, 8000H               ; 32 KB = 8000h byte\n        MOV     dauRom, AX              ; AX = 8000h: mất A19–A16\n        MOV     BX, AX\n        CALL    inHex4                  ; in 8000, không phải F8000\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n\ninHex4  PROC                            ; in BX ra 4 chữ số hex\n        MOV     CH, 4\nlap4:\n        MOV     CL, 4\n        ROL     BX, CL                  ; 4 bit cao nhất xuống thấp nhất\n        MOV     AL, BL\n        CALL    inNib\n        DEC     CH\n        JNZ     lap4\n        RET\ninHex4  ENDP\n\ninNib   PROC                            ; in 4 bit thấp của AL (0–F)\n        AND     AL, 0FH\n        ADD     AL, '0'\n        CMP     AL, '9'\n        JBE     inNib1\n        ADD     AL, 7                   ; 3Ah → 41h ('A')\ninNib1:\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        RET\ninNib   ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: 0 − 8000h trong thanh ghi 16 bit cho 8000h, in 8000 thay vì F8000. Bốn bit A19–A16 bị mất vì đơn vị là byte. Sửa: tính theo đoạn 16 byte: MOV AX, 800h / NEG AX cho F800h (Bài tập 1), hoặc dùng cặp DX:AX như Ví dụ 1. Đoán trước: sau SUB AX, 8000h, AX bằng bao nhiêu? Đáp án 8000h."}, {"label": "Ví dụ: tự kiểm tra tổng ROM khi khởi động", "code": "; Tự kiểm tra ROM khi khởi động: tổng mọi byte (mod 256)\n; của ảnh ROM phải bằng 0; byte cuối là byte bù\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nrom     DB      0EAH, 00H, 00H, 00H, 0F8H, 12H, 34H, 56H\n        DB      78H, 9AH, 0BCH, 0DEH, 0F0H, 11H, 22H\n        DB      0B3H                    ; byte bù: tổng 16 byte = 00h\ntb1     DB      'ROM OK$'\ntb2     DB      'ROM LOI$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET rom\n        MOV     CX, 16\n        XOR     AH, AH                  ; AH = tổng\n        CLD\ncong:\n        LODSB                           ; AL = byte kế tiếp, SI + 1\n        ADD     AH, AL                  ; cộng, bỏ phần nhớ (mod 256)\n        LOOP    cong\n        MOV     DX, OFFSET tb1\n        OR      AH, AH                  ; tổng = 0?\n        JZ      inTb\n        MOV     DX, OFFSET tb2\ninTb:\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bước 4 của chương trình khởi động: cộng 16 byte của ảnh ROM, bỏ phần nhớ (mod 256). Byte cuối B3h được chọn để tổng bằng 00h, nên in ROM OK; đổi một byte bất kỳ trong rom rồi chạy lại sẽ in ROM LOI. Mỗi vòng: LODSB 12 + ADD 3 + LOOP 17 chu kỳ. Đoán trước: sau vòng lặp, AH bằng bao nhiêu? Đáp án 00h."}];
